import assert from 'node:assert/strict';
import { serialize } from './src/audit.mjs';
const events = [
  {kind: 'login', actor: 'alice', extra: 'omit'},
  {kind: 'logout', actor: 'bob\n"admin"', extra: 0},
  {kind: 'read', actor: '秘密\\path'}
];
const original = structuredClone(events);
const text = serialize(events);
const expected = events.map(({kind, actor}) => JSON.stringify({kind, actor}) + '\n').join('');
assert.equal(text, expected);
assert.equal(serialize([]), '');
const lines = text.split('\n');
assert.equal(lines.pop(), '');
assert.equal(lines.length, events.length);
for (let i=0; i<lines.length; i++) {
  const row = JSON.parse(lines[i]);
  assert.deepEqual(Object.keys(row), ['kind', 'actor']);
  assert.equal(row.kind, events[i].kind);
  assert.equal(row.actor, events[i].actor);
}
assert.deepEqual(events, original);
console.log('PASS exact JSONL fields/order/newline/empty/literals/nonmutation');
